<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { AuthCredentials } from '../api/auth'
import {
  changeOntologyStatus, compareOntologyReleases, createOntology, createOntologyClass, createOntologyProperty, createOntologyRelation, deleteOntologyClass, deleteOntologyProperty, deleteOntologyRelation, forkOntology, updateOntologyProperty, updateOntologyRelation, validateOntology,
  getOntologyLayout, listOntologyClasses, listOntologyProperties, listOntologyRelations, listOntologyReleases,
  listOntologies, releaseOntology, saveOntologyLayout, updateOntology, type Ontology, type OntologyClass, type OntologyProperty,
  type OntologyRelation, type OntologyRelease, type OntologyPropertyValueType, type OntologyRelationCardinality,
} from '../api/ontology'
import { listProjects, type Project } from '../api/projects'

const props = defineProps<{ credentials: AuthCredentials | null }>()
const projects = ref<Project[]>([])
const ontologies = ref<Ontology[]>([])
const classes = ref<OntologyClass[]>([])
const properties = ref<OntologyProperty[]>([])
const relations = ref<OntologyRelation[]>([])
const releases = ref<OntologyRelease[]>([])
const projectId = ref(''); const ontologyId = ref(''); const classId = ref('')
const ontologyName = ref(''); const className = ref(''); const propertyName = ref(''); const relationName = ref('')
const valueType = ref<OntologyPropertyValueType>('TEXT'); const required = ref(false)
const sourceClassId = ref(''); const targetClassId = ref(''); const cardinality = ref<OntologyRelationCardinality>('ONE_TO_MANY')
const releaseVersion = ref('0.1.0'); const releaseNotes = ref('')
const forkName = ref(''); const validationIssues = ref<Array<{ severity: string; code: string; message: string; location: string }>>([])
const requireClassProperties = ref(false); const allowSelfRelations = ref(true); const savingRules = ref(false)
const editingPropertyId = ref(''); const editingRelationId = ref(''); const editPropertyName = ref(''); const editPropertyType = ref<OntologyPropertyValueType>('TEXT'); const editPropertyRequired = ref(false); const editRelationName = ref(''); const editSourceClassId = ref(''); const editTargetClassId = ref(''); const editCardinality = ref<OntologyRelationCardinality>('ONE_TO_MANY')
const nodePositions = ref<Record<string, { x: number; y: number }>>({}); const graphZoom = ref(1); const draggingNodeId = ref(''); const selectedRelationId = ref('')
const selectedNodeIds = ref<string[]>([]); const dragStart = ref<{ x: number; y: number } | null>(null); const dragOrigin = ref<Record<string, { x: number; y: number }>>({}); const layoutSaving = ref(false)
const fromReleaseId = ref(''); const toReleaseId = ref(''); const releaseDiff = ref<{ fromVersion: string; toVersion: string; changes: Array<{ itemId: string; kind: string; changeType: string; name: string; location: string; before?: unknown; after?: unknown }> } | null>(null)
const message = ref(''); const error = ref(''); const loading = ref(false)
const selectedOntology = computed(() => ontologies.value.find(item => item.id === ontologyId.value))
const selectedClass = computed(() => classes.value.find(item => item.id === classId.value))
const latestRelease = computed(() => releases.value[0])
const counts = computed(() => ({ classes: classes.value.length, properties: properties.value.length, relations: relations.value.length }))
const diff = computed(() => latestRelease.value ? { classes: counts.value.classes - latestRelease.value.classCount, properties: counts.value.properties - latestRelease.value.propertyCount, relations: counts.value.relations - latestRelease.value.relationCount } : counts.value)
const graphNodes = computed(() => classes.value.map((item, index) => ({ ...item, x: nodePositions.value[item.id]?.x ?? 30 + (index % 3) * 190, y: nodePositions.value[item.id]?.y ?? 32 + Math.floor(index / 3) * 92 })))
const graphNodeMap = computed(() => new Map(graphNodes.value.map(item => [item.id, item])))
const graphEdges = computed(() => relations.value.map(item => ({ ...item, source: graphNodeMap.value.get(item.sourceClassId), target: graphNodeMap.value.get(item.targetClassId) })).filter(item => item.source && item.target))
const selectedRelation = computed(() => relations.value.find(item => item.id === selectedRelationId.value))
const credentials = () => props.credentials ?? undefined
function formatValue(value: unknown) { return value == null ? '—' : JSON.stringify(value, null, 2) }

async function loadProjects() { projects.value = await listProjects(credentials()); if (!projectId.value && projects.value[0]) projectId.value = projects.value[0].id; await loadOntologies() }
async function loadOntologies() { if (!projectId.value) return; const previous = ontologyId.value; ontologies.value = await listOntologies(projectId.value, credentials()); ontologyId.value = ontologies.value.find(item => item.id === previous)?.id ?? ontologies.value[0]?.id ?? ''; await loadModel() }
async function loadModel() {
  if (!projectId.value || !ontologyId.value) { classes.value = []; properties.value = []; relations.value = []; releases.value = []; return }
  classes.value = await listOntologyClasses(projectId.value, ontologyId.value, credentials()); classId.value = classes.value[0]?.id ?? ''; forkName.value = selectedOntology.value ? `${selectedOntology.value.name} draft` : ''; requireClassProperties.value = selectedOntology.value?.requireClassProperties ?? false; allowSelfRelations.value = selectedOntology.value?.allowSelfRelations ?? true; validationIssues.value = []; selectedRelationId.value = ''; selectedNodeIds.value = []; graphZoom.value = 1; await loadLayout()
  const positions = { ...nodePositions.value }; try { const stored = localStorage.getItem(`entloom:ontology-layout:${ontologyId.value}`); if (stored) Object.assign(positions, JSON.parse(stored)) } catch { /* ignore malformed local layout */ } classes.value.forEach((item, index) => { positions[item.id] ||= { x: 30 + (index % 3) * 190, y: 32 + Math.floor(index / 3) * 92 } }); nodePositions.value = positions
  await Promise.all([loadProperties(), loadRelations(), loadReleases()])
}
async function loadProperties() { properties.value = projectId.value && ontologyId.value && classId.value ? await listOntologyProperties(projectId.value, ontologyId.value, classId.value, credentials()) : [] }
async function loadLayout() { if (!projectId.value || !ontologyId.value) return; try { const layout = await getOntologyLayout(projectId.value, ontologyId.value, credentials()); nodePositions.value = { ...layout.positions } } catch { nodePositions.value = {} } }
async function loadRelations() { relations.value = projectId.value && ontologyId.value ? await listOntologyRelations(projectId.value, ontologyId.value, credentials()) : [] }
async function loadReleases() { releases.value = projectId.value && ontologyId.value ? await listOntologyReleases(projectId.value, ontologyId.value, credentials()) : []; fromReleaseId.value = releases.value[1]?.id || ''; toReleaseId.value = releases.value[0]?.id || ''; releaseDiff.value = null }
async function run(action: () => Promise<void>) { loading.value = true; error.value = ''; message.value = ''; try { await action() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Request failed' } finally { loading.value = false } }
async function submitOntology() { if (!projectId.value || !ontologyName.value.trim()) return; await run(async () => { const item = await createOntology(projectId.value, ontologyName.value.trim(), '', credentials()); ontologyName.value = ''; await loadOntologies(); ontologyId.value = item.id; await loadModel(); message.value = 'Ontology created' }) }
async function submitClass() { if (!projectId.value || !ontologyId.value || !className.value.trim()) return; await run(async () => { await createOntologyClass(projectId.value, ontologyId.value, className.value.trim(), '', credentials()); className.value = ''; await loadModel(); message.value = 'Class created' }) }
async function submitProperty() { if (!projectId.value || !ontologyId.value || !classId.value || !propertyName.value.trim()) return; await run(async () => { await createOntologyProperty(projectId.value, ontologyId.value, classId.value, { name: propertyName.value.trim(), description: '', valueType: valueType.value, required: required.value }, credentials()); propertyName.value = ''; await loadProperties(); message.value = 'Property added' }) }
async function submitRelation() { if (!projectId.value || !ontologyId.value || !sourceClassId.value || !targetClassId.value || !relationName.value.trim()) return; await run(async () => { await createOntologyRelation(projectId.value, ontologyId.value, { name: relationName.value.trim(), description: '', sourceClassId: sourceClassId.value, targetClassId: targetClassId.value, cardinality: cardinality.value }, credentials()); relationName.value = ''; await loadRelations(); message.value = 'Relation added' }) }
function startPropertyEdit(item: OntologyProperty) { editingPropertyId.value = item.id; editPropertyName.value = item.name; editPropertyType.value = item.valueType; editPropertyRequired.value = item.required }
async function savePropertyEdit(item: OntologyProperty) { if (!projectId.value || !ontologyId.value || !editPropertyName.value.trim()) return; await run(async () => { await updateOntologyProperty(projectId.value, ontologyId.value, item.classId, item.id, { name: editPropertyName.value.trim(), description: item.description || '', valueType: editPropertyType.value, required: editPropertyRequired.value }, credentials()); editingPropertyId.value = ''; await loadProperties(); message.value = 'Property updated' }) }
function startRelationEdit(item: OntologyRelation) { editingRelationId.value = item.id; editRelationName.value = item.name; editSourceClassId.value = item.sourceClassId; editTargetClassId.value = item.targetClassId; editCardinality.value = item.cardinality }
async function saveRelationEdit(item: OntologyRelation) { if (!projectId.value || !ontologyId.value || !editRelationName.value.trim()) return; await run(async () => { await updateOntologyRelation(projectId.value, ontologyId.value, item.id, { name: editRelationName.value.trim(), description: item.description || '', sourceClassId: editSourceClassId.value, targetClassId: editTargetClassId.value, cardinality: editCardinality.value }, credentials()); editingRelationId.value = ''; await loadRelations(); message.value = 'Relation updated' }) }
async function removeClass(id: string) { if (!projectId.value || !ontologyId.value) return; await run(async () => { await deleteOntologyClass(projectId.value, ontologyId.value, id, credentials()); await loadModel(); message.value = 'Class deleted' }) }
async function removeProperty(id: string) { if (!projectId.value || !ontologyId.value || !classId.value) return; await run(async () => { await deleteOntologyProperty(projectId.value, ontologyId.value, classId.value, id, credentials()); await loadProperties(); message.value = 'Property deleted' }) }
async function removeRelation(id: string) { if (!projectId.value || !ontologyId.value) return; await run(async () => { await deleteOntologyRelation(projectId.value, ontologyId.value, id, credentials()); await loadRelations(); message.value = 'Relation deleted' }) }
async function saveValidationRules() { if (!projectId.value || !ontologyId.value || !selectedOntology.value) return; savingRules.value = true; await run(async () => { await updateOntology(projectId.value, ontologyId.value, { name: selectedOntology.value!.name, description: selectedOntology.value!.description || '', requireClassProperties: requireClassProperties.value, allowSelfRelations: allowSelfRelations.value }, credentials()); await loadOntologies(); message.value = 'Validation rules saved' }); savingRules.value = false }
async function publish() { if (!projectId.value || !ontologyId.value || !releaseVersion.value.trim()) return; await run(async () => { const validation = await validateOntology(projectId.value, ontologyId.value, credentials()); validationIssues.value = validation.issues; if (!validation.valid) { message.value = 'Fix validation errors before publishing'; return } await releaseOntology(projectId.value, ontologyId.value, releaseVersion.value.trim(), credentials(), releaseNotes.value.trim()); await loadOntologies(); await loadModel(); message.value = `Ontology released as ${releaseVersion.value}` }) }
async function startDraft() { if (!projectId.value || !ontologyId.value) return; await run(async () => { await changeOntologyStatus(projectId.value, ontologyId.value, 'DRAFT', credentials()); await loadOntologies(); message.value = 'Draft reopened for the next version' }) }
async function forkDraft() { if (!projectId.value || !ontologyId.value || !forkName.value.trim()) return; await run(async () => { const fork = await forkOntology(projectId.value, ontologyId.value, forkName.value.trim(), '', credentials()); await loadOntologies(); ontologyId.value = fork.id; await loadModel(); message.value = 'Draft fork created' }) }
async function compareReleases() { if (!projectId.value || !ontologyId.value || !fromReleaseId.value || !toReleaseId.value || fromReleaseId.value === toReleaseId.value) return; await run(async () => { releaseDiff.value = await compareOntologyReleases(projectId.value, ontologyId.value, fromReleaseId.value, toReleaseId.value, credentials()) }) }
function selectNode(event: MouseEvent, id: string) { if (event.metaKey || event.ctrlKey) selectedNodeIds.value = selectedNodeIds.value.includes(id) ? selectedNodeIds.value.filter(item => item !== id) : [...selectedNodeIds.value, id]; else selectedNodeIds.value = [id]; classId.value = id; loadProperties() }
function startNodeDrag(event: PointerEvent, id: string) { if (selectedOntology.value?.status !== 'DRAFT') return; if (!selectedNodeIds.value.includes(id)) selectedNodeIds.value = [id]; draggingNodeId.value = id; dragStart.value = { x: event.clientX, y: event.clientY }; dragOrigin.value = Object.fromEntries(selectedNodeIds.value.map(nodeId => [nodeId, { ...(nodePositions.value[nodeId] || graphNodes.value.find(node => node.id === nodeId)!) }])) as Record<string, { x: number; y: number }>; (event.currentTarget as SVGElement).setPointerCapture?.(event.pointerId) }
function moveNode(event: PointerEvent) { if (!draggingNodeId.value || !dragStart.value) return; const svg = event.currentTarget as SVGSVGElement; const rect = svg.getBoundingClientRect(); const dx = (event.clientX - dragStart.value.x) / rect.width * 600 / graphZoom.value; const dy = (event.clientY - dragStart.value.y) / rect.height * 260 / graphZoom.value; const next = { ...nodePositions.value }; selectedNodeIds.value.forEach(id => { const origin = dragOrigin.value[id]; if (origin) next[id] = { x: Math.max(8, Math.min(447, origin.x + dx)), y: Math.max(8, Math.min(210, origin.y + dy)) } }); nodePositions.value = next }
function endNodeDrag() { if (!draggingNodeId.value) return; draggingNodeId.value = ''; dragStart.value = null; void persistLayout() }
async function persistLayout() { if (!projectId.value || !ontologyId.value || !Object.keys(nodePositions.value).length) return; layoutSaving.value = true; try { await saveOntologyLayout(projectId.value, ontologyId.value, nodePositions.value, credentials()) } catch { /* keep the local layout usable if the server is temporarily unavailable */ } finally { layoutSaving.value = false } }
async function autoLayout() { if (!classes.value.length) return; const incoming = new Map(classes.value.map(item => [item.id, 0])); relations.value.forEach(item => incoming.set(item.targetClassId, (incoming.get(item.targetClassId) || 0) + 1)); const levels = new Map<string, number>(); const queue = classes.value.filter(item => !incoming.get(item.id)).map(item => item.id); queue.forEach(id => levels.set(id, 0)); for (const id of queue) relations.value.filter(item => item.sourceClassId === id).forEach(item => { levels.set(item.targetClassId, Math.max(levels.get(item.targetClassId) || 0, (levels.get(id) || 0) + 1)); queue.push(item.targetClassId) }); classes.value.forEach(item => { if (!levels.has(item.id)) levels.set(item.id, 0) }); const grouped = new Map<number, string[]>(); levels.forEach((level, id) => grouped.set(level, [...(grouped.get(level) || []), id])); const next: Record<string, { x: number; y: number }> = {}; grouped.forEach((ids, level) => ids.forEach((id, index) => { next[id] = { x: 30 + (level % 3) * 190, y: 32 + (index % 3) * 78 } })); nodePositions.value = next; selectedNodeIds.value = []; await persistLayout(); message.value = 'Graph auto-layout saved' }
function zoomGraph(event?: WheelEvent, factor?: number) { if (event) event.preventDefault(); graphZoom.value = Math.max(.65, Math.min(1.8, graphZoom.value * (factor ?? (event && event.deltaY < 0 ? 1.1 : .9)))) }
onMounted(() => run(loadProjects))
</script>

<template>
  <section class="workspace" aria-labelledby="ontology-heading">
    <div class="workspace-heading"><div><span class="eyebrow">Ontology studio</span><h2 id="ontology-heading">Model a business context</h2><p>Define classes, properties and relations, then publish a versioned release with a visible change summary.</p></div><span class="api-badge">API v1</span></div>
    <p v-if="error" class="state-message error-message">{{ error }}</p><p v-if="message" class="state-message">{{ message }}</p>
    <div class="ontology-toolbar"><label>Project<select v-model="projectId" @change="loadOntologies"><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><label>Ontology<select v-model="ontologyId" @change="loadModel"><option v-for="ontology in ontologies" :key="ontology.id" :value="ontology.id">{{ ontology.name }} · {{ ontology.status }}</option></select></label></div>
    <div class="workspace-grid">
      <form class="project-form" @submit.prevent="submitOntology"><span class="section-label">Ontology</span><h3>Create a model</h3><input v-model="ontologyName" required maxlength="120" placeholder="e.g. Customer context" /><button class="primary" :disabled="loading || !projectId || !ontologyName.trim()">Create ontology</button></form>
      <div class="project-list"><div class="list-heading"><div><span class="section-label">Classes</span><h3>{{ classes.length }} class<span v-if="classes.length !== 1">es</span></h3></div><span class="status-badge">{{ selectedOntology?.status || 'EMPTY' }}</span></div><form v-if="selectedOntology?.status === 'DRAFT'" class="inline-form" @submit.prevent="submitClass"><input v-model="className" required maxlength="120" placeholder="Add a class, e.g. Customer" /><button class="primary" :disabled="loading || !className.trim()">Add class</button></form><p v-if="!ontologyId" class="state-message">Create or select an ontology to start modeling.</p><ul v-else class="project-items"><li v-for="item in classes" :key="item.id" class="project-item" :class="{ selected: classId === item.id }"><button type="button" class="item-select" @click="classId = item.id; loadProperties()"><strong>{{ item.name }}</strong><span>{{ item.description || 'Class definition' }}</span></button><span class="item-actions"><span class="status-badge">{{ properties.length && classId === item.id ? `${properties.length} props` : 'CLASS' }}</span><button v-if="selectedOntology?.status === 'DRAFT'" class="delete-button" type="button" @click="removeClass(item.id)">Delete</button></span></li></ul></div>
    </div>
    <section v-if="selectedOntology" class="graph-card"><div class="list-heading"><div><span class="section-label">Graph canvas</span><h3>Business context map</h3></div><div class="graph-controls"><button class="quiet-button" type="button" @click="autoLayout">Auto layout</button><button class="quiet-button" type="button" @click="zoomGraph(undefined, .85)">−</button><span>{{ Math.round(graphZoom * 100) }}%</span><button class="quiet-button" type="button" @click="zoomGraph(undefined, 1.15)">+</button><span v-if="layoutSaving" class="layout-saving">Saving…</span><span class="api-badge">{{ selectedNodeIds.length }} selected · {{ relations.length }} edges</span></div></div><div class="graph-layout"><svg class="ontology-graph" viewBox="0 0 600 260" role="img" aria-label="Ontology graph" @pointermove="moveNode" @pointerup="endNodeDrag" @pointerleave="endNodeDrag" @wheel.prevent="zoomGraph($event)"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill="#8ab85d" /></marker></defs><g :transform="`scale(${graphZoom})`"><g v-for="edge in graphEdges" :key="edge.id"><line :x1="(edge.source?.x || 0) + 72" :y1="(edge.source?.y || 0) + 22" :x2="edge.target?.x || 0" :y2="(edge.target?.y || 0) + 22" class="graph-edge" :class="{ selected: selectedRelationId === edge.id }" marker-end="url(#arrow)" @click.stop="selectedRelationId = edge.id" /><text :x="((edge.source?.x || 0) + (edge.target?.x || 0)) / 2" :y="((edge.source?.y || 0) + (edge.target?.y || 0)) / 2" class="graph-edge-label">{{ edge.name }}</text></g><g v-for="node in graphNodes" :key="node.id" class="graph-node" :class="{ active: classId === node.id }" @pointerdown.stop="startNodeDrag($event, node.id)" @click="selectNode($event, node.id)"><rect :x="node.x" :y="node.y" width="145" height="44" rx="9" /><text :x="node.x + 12" :y="node.y + 19">{{ node.name }}</text><text :x="node.x + 12" :y="node.y + 34" class="graph-node-meta">{{ properties.length && classId === node.id ? properties.length : 'class' }}</text></g></g></svg><div class="mini-map-wrap"><span class="section-label">Mini map</span><svg class="mini-map" viewBox="0 0 600 260" aria-label="Ontology mini map"><line v-for="edge in graphEdges" :key="`mini-${edge.id}`" :x1="(edge.source?.x || 0) + 72" :y1="(edge.source?.y || 0) + 22" :x2="edge.target?.x || 0" :y2="(edge.target?.y || 0) + 22" class="mini-edge" /><rect v-for="node in graphNodes" :key="`mini-${node.id}`" :x="node.x" :y="node.y" width="145" height="44" rx="5" :class="{ selected: selectedNodeIds.includes(node.id) }" @click="selectNode($event, node.id)" /></svg></div><aside v-if="selectedRelation" class="relation-sidebar"><div class="list-heading"><div><span class="section-label">Relation details</span><h3>{{ selectedRelation.name }}</h3></div><button class="quiet-button" type="button" @click="selectedRelationId = ''">Close</button></div><dl class="detail-list"><dt>From</dt><dd>{{ classes.find(item => item.id === selectedRelation?.sourceClassId)?.name || 'Unknown class' }}</dd><dt>To</dt><dd>{{ classes.find(item => item.id === selectedRelation?.targetClassId)?.name || 'Unknown class' }}</dd><dt>Cardinality</dt><dd>{{ selectedRelation.cardinality }}</dd><dt>Description</dt><dd>{{ selectedRelation.description || 'No description' }}</dd></dl><button v-if="selectedOntology.status === 'DRAFT'" class="primary" type="button" @click="startRelationEdit(selectedRelation)">Edit relation</button></aside></div><p v-if="!classes.length" class="state-message">Add classes to see the context graph.</p></section>
    <div v-if="selectedOntology" class="model-grid">
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Properties</span><h3>{{ selectedClass?.name || 'Select a class' }}</h3></div><span class="api-badge">{{ properties.length }}</span></div><form v-if="selectedOntology.status === 'DRAFT' && selectedClass" class="stack-form" @submit.prevent="submitProperty"><input v-model="propertyName" required maxlength="120" placeholder="Property name, e.g. email" /><div class="form-row"><select v-model="valueType"><option value="TEXT">TEXT</option><option value="NUMBER">NUMBER</option><option value="BOOLEAN">BOOLEAN</option><option value="DATE">DATE</option><option value="REFERENCE">REFERENCE</option></select><label class="check-label"><input v-model="required" type="checkbox" /> required</label><button class="primary" :disabled="loading || !propertyName.trim()">Add</button></div></form><ul class="project-items"><li v-for="item in properties" :key="item.id" class="project-item"><form v-if="editingPropertyId === item.id" class="edit-form" @submit.prevent="savePropertyEdit(item)"><input v-model="editPropertyName" required maxlength="120" /><select v-model="editPropertyType"><option value="TEXT">TEXT</option><option value="NUMBER">NUMBER</option><option value="BOOLEAN">BOOLEAN</option><option value="DATE">DATE</option><option value="REFERENCE">REFERENCE</option></select><label class="check-label"><input v-model="editPropertyRequired" type="checkbox" /> required</label><button class="primary" type="submit">Save</button><button class="quiet-button" type="button" @click="editingPropertyId = ''">Cancel</button></form><template v-else><div><strong>{{ item.name }}</strong><span>{{ item.valueType }} · {{ item.required ? 'required' : 'optional' }}</span></div><span class="item-actions"><span class="status-badge">PROP</span><button v-if="selectedOntology.status === 'DRAFT'" class="quiet-button" type="button" @click="startPropertyEdit(item)">Edit</button><button v-if="selectedOntology.status === 'DRAFT'" class="delete-button" type="button" @click="removeProperty(item.id)">Delete</button></span></template></li></ul><p v-if="selectedClass && !properties.length" class="state-message">No properties defined for this class.</p></section>
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Relations</span><h3>{{ relations.length }} relation<span v-if="relations.length !== 1">s</span></h3></div><span class="api-badge">GRAPH</span></div><form v-if="selectedOntology.status === 'DRAFT' && classes.length > 1" class="stack-form" @submit.prevent="submitRelation"><input v-model="relationName" required maxlength="120" placeholder="Relation name, e.g. owns" /><div class="form-row"><select v-model="sourceClassId"><option value="">From class</option><option v-for="item in classes" :key="`source-${item.id}`" :value="item.id">{{ item.name }}</option></select><select v-model="targetClassId"><option value="">To class</option><option v-for="item in classes" :key="`target-${item.id}`" :value="item.id">{{ item.name }}</option></select></div><div class="form-row"><select v-model="cardinality"><option value="ONE_TO_ONE">ONE_TO_ONE</option><option value="ONE_TO_MANY">ONE_TO_MANY</option><option value="MANY_TO_ONE">MANY_TO_ONE</option><option value="MANY_TO_MANY">MANY_TO_MANY</option></select><button class="primary" :disabled="loading || !relationName.trim() || !sourceClassId || !targetClassId">Add relation</button></div></form><ul class="project-items"><li v-for="item in relations" :key="item.id" class="project-item"><form v-if="editingRelationId === item.id" class="edit-form relation-edit" @submit.prevent="saveRelationEdit(item)"><input v-model="editRelationName" required maxlength="120" /><select v-model="editSourceClassId"><option v-for="candidate in classes" :key="`edit-source-${candidate.id}`" :value="candidate.id">{{ candidate.name }}</option></select><select v-model="editTargetClassId"><option v-for="candidate in classes" :key="`edit-target-${candidate.id}`" :value="candidate.id">{{ candidate.name }}</option></select><select v-model="editCardinality"><option value="ONE_TO_ONE">ONE_TO_ONE</option><option value="ONE_TO_MANY">ONE_TO_MANY</option><option value="MANY_TO_ONE">MANY_TO_ONE</option><option value="MANY_TO_MANY">MANY_TO_MANY</option></select><button class="primary" type="submit">Save</button><button class="quiet-button" type="button" @click="editingRelationId = ''">Cancel</button></form><template v-else><div><strong>{{ item.name }}</strong><span>{{ classes.find(c => c.id === item.sourceClassId)?.name || '?' }} → {{ classes.find(c => c.id === item.targetClassId)?.name || '?' }} · {{ item.cardinality }}</span></div><span class="item-actions"><span class="status-badge">EDGE</span><button v-if="selectedOntology.status === 'DRAFT'" class="quiet-button" type="button" @click="startRelationEdit(item)">Edit</button><button v-if="selectedOntology.status === 'DRAFT'" class="delete-button" type="button" @click="removeRelation(item.id)">Delete</button></span></template></li></ul><p v-if="!relations.length" class="state-message">Add two classes to define the first relation.</p></section>
    </div>
    <section v-if="selectedOntology && selectedOntology.status === 'DRAFT'" class="rules-card"><div class="list-heading"><div><span class="section-label">Validation rules</span><h3>Release policy</h3></div><span class="api-badge">CONFIG</span></div><label class="rule-toggle"><input v-model="requireClassProperties" type="checkbox" /><span><strong>Require properties on every class</strong><small>Blocks release when a class has no properties.</small></span></label><label class="rule-toggle"><input v-model="allowSelfRelations" type="checkbox" /><span><strong>Allow self-relations</strong><small>Keep enabled to allow a class to relate to itself.</small></span></label><button class="quiet-button" type="button" :disabled="savingRules || loading" @click="saveValidationRules">{{ savingRules ? 'Saving…' : 'Save validation rules' }}</button></section>
    <section v-if="selectedOntology && validationIssues.length" class="validation-card"><div class="list-heading"><div><span class="section-label">Preflight</span><h3>Release validation</h3></div><span class="api-badge">{{ validationIssues.filter(item => item.severity === 'ERROR').length }} errors</span></div><ul class="validation-list"><li v-for="issue in validationIssues" :key="`${issue.code}-${issue.location}`" :class="issue.severity.toLowerCase()"><strong>{{ issue.severity }}</strong><span>{{ issue.message }}</span><small>{{ issue.location }}</small></li></ul></section>
    <div v-if="selectedOntology" class="release-grid">
      <section class="project-list"><div class="list-heading"><div><span class="section-label">Release</span><h3>Publish a contract</h3></div><span class="api-badge">{{ counts.classes + counts.properties + counts.relations }} nodes</span></div><form v-if="selectedOntology.status === 'DRAFT'" class="stack-form" @submit.prevent="publish"><div class="form-row"><input v-model="releaseVersion" required pattern="\\d+\\.\\d+\\.\\d+" placeholder="0.1.0" /><button class="primary" :disabled="loading || !releaseVersion.trim()">Validate & publish</button></div><input v-model="releaseNotes" maxlength="2000" placeholder="Release notes (optional)" /></form><div v-else class="state-message"><p>This ontology is released and read-only.</p><button class="quiet-button" type="button" :disabled="loading" @click="startDraft">Start next draft</button><form class="stack-form fork-form" @submit.prevent="forkDraft"><input v-model="forkName" required maxlength="120" placeholder="Fork name" /><button class="quiet-button" type="submit" :disabled="loading || !forkName.trim()">Fork as draft</button></form></div><div class="diff-card"><span class="section-label">Current draft changes</span><strong>{{ latestRelease ? 'Current model vs ' + latestRelease.version : 'Unreleased changes' }}</strong><div class="diff-row"><span>Classes</span><b :class="{ positive: diff.classes > 0 }">{{ diff.classes > 0 ? '+' : '' }}{{ diff.classes }}</b><span>Properties</span><b :class="{ positive: diff.properties > 0 }">{{ diff.properties > 0 ? '+' : '' }}{{ diff.properties }}</b><span>Relations</span><b :class="{ positive: diff.relations > 0 }">{{ diff.relations > 0 ? '+' : '' }}{{ diff.relations }}</b></div></div></section>
      <section class="project-list"><div class="list-heading"><div><span class="section-label">History</span><h3>{{ releases.length }} release<span v-if="releases.length !== 1">s</span></h3></div><span class="api-badge">AUDIT</span></div><div v-if="releases.length > 1" class="stack-form"><div class="form-row"><select v-model="fromReleaseId"><option value="">Compare from…</option><option v-for="item in releases" :key="`from-${item.id}`" :value="item.id">{{ item.version }}</option></select><select v-model="toReleaseId"><option value="">Compare to…</option><option v-for="item in releases" :key="`to-${item.id}`" :value="item.id">{{ item.version }}</option></select><button class="primary" type="button" :disabled="loading || !fromReleaseId || !toReleaseId || fromReleaseId === toReleaseId" @click="compareReleases">Compare</button></div></div><div v-if="releaseDiff" class="diff-card"><span class="section-label">Version comparison</span><strong>{{ releaseDiff.fromVersion }} → {{ releaseDiff.toVersion }}</strong><ul class="project-items"><li v-for="(change, index) in releaseDiff.changes" :key="`${change.itemId}-${index}`" class="project-item change-item"><details><summary><span><strong>{{ change.name }}</strong><small>{{ change.location }} · {{ change.kind }}</small></span><span class="status-badge" :data-change="change.changeType">{{ change.changeType }}</span></summary><div class="change-values"><div><span class="section-label">Before</span><pre>{{ formatValue(change.before) }}</pre></div><div><span class="section-label">After</span><pre>{{ formatValue(change.after) }}</pre></div></div></details></li></ul><p v-if="!releaseDiff.changes.length" class="state-message">No item-level changes between these releases.</p></div><ul class="project-items"><li v-for="item in releases" :key="item.id" class="project-item"><div><strong>{{ item.version }}</strong><span>{{ item.classCount }} classes · {{ item.propertyCount }} props · {{ item.relationCount }} relations</span></div><span class="status-badge">{{ item.releasedBy || 'system' }}</span></li></ul><p v-if="!releases.length" class="state-message">No releases yet. Publish the draft when the model is ready.</p></section>
    </div>
  </section>
</template>
